 let {data}=$props();let t=$derived(translator(data.lang));let model=$derived(data.model);let ready=$state(false),offline=$state(false),pending=$state<Draft[]>([]),message=$state('');let pane=$state('overview'),action=$state(''),defaults=$state<Record<string,string>>({}),dirty=$state(false),actionDialog=$state<HTMLDialogElement>();let lastSection=$state('');
