 let primary=$derived(permitted.includes(preferred[data.section])?preferred[data.section]:permitted[0]);
 $effect(()=>{if(lastSection!==data.section){lastSection=data.section;pane='overview';actionDialog?.close();action='';dirty=false;}});
 async function openAction(type:string,values:Record<string,string>={}){if(!allowed(type,data.tenant.role)||!permitted.includes(type))return;defaults=values;action=type;dirty=false;await tick();if(actionDialog&&!actionDialog.open)actionDialog.showModal();}
 function closeAction(){if(dirty&&!confirm(t('uxDiscard')))return;actionDialog?.close();dirty=false;action='';}
