<style>.page-header{display:flex;align-items:center;justify-content:space-between;gap:24px;margin-bottom:24px}.page-header .eyebrow{margin:0 0 8px}.page-intro{color:var(--muted);font-size:13px;max-width:660px;margin:0}.page-actions{display:flex;gap:10px;align-items:center;flex-shrink:0}.primary-action,.button-link{display:inline-flex;align-items:center;justify-content:center;gap:9px;font-size:12px}.page-actions .secondary{font-size:12px}.button-link{padding:12px 16px;background:var(--brand);border-radius:9px;text-decoration:none;color:white;min-height:44px;font-weight:650}.view-tabs{display:flex;gap:22px;border-bottom:1px solid #dce6de;margin-bottom:24px;overflow:auto}.view-tabs button{border-radius:0;color:var(--muted);background:transparent;padding:12px 2px;border-bottom:2px solid transparent;font-size:12px;white-space:nowrap;min-height:48px;font-weight:550}.view-tabs button.chosen{color:var(--brand);border-bottom-color:var(--brand);font-weight:700}.view-tabs span{padding:2px 6px;border-radius:5px;background:#eaf0eb;color:#496453;font-size:10px;margin-left:7px}.module-workspace{min-width:0}.register-heading{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:16px}.register-heading h2{margin:0}.action-picker{margin-bottom:18px}.action-hub>div{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:10px}.action-hub button{display:flex;justify-content:space-between;gap:12px;align-items:center;font-size:12px;text-align:left}.download-link{padding:10px 16px;border:1px solid var(--line);border-radius:8px;text-decoration:none;font-size:12px}.draft-row{padding:16px 0;border-bottom:1px solid var(--line);font-size:12px}code{overflow-wrap:anywhere}@media(max-width:1100px){.page-header{align-items:flex-start;flex-direction:column;gap:18px}.page-actions{flex-wrap:wrap}}@media(max-width:640px){.page-actions{width:100%}.primary-action{flex:1}.view-tabs{gap:16px}.view-tabs button{font-size:11px}.view-tabs span{display:none}}
